from itertools import combinations


def interleave(a, b):
    """枚举两个序列的所有交错（保持各自内部相对顺序）。"""
    out = []
    for ia in combinations(range(len(a) + len(b)), len(a)):
        ib = [i for i in range(len(a) + len(b)) if i not in ia]
        seq = [None] * (len(a) + len(b))
        for pos, i in zip(ia, a):
            seq[pos] = ("W", i)
        for pos, i in zip(ib, b):
            seq[pos] = ("R", i)
        out.append(seq)
    return out


def simulate(seq):
    """读线程固定 3 步（GET_MISS → READ_DB → SET_CACHE）。返回最终 (cache, db)。"""
    db = "OLD"
    cache = {"k": "OLD"}
    read_buf = None
    for who, step in seq:
        if who == "W":
            if step == "DEL":
                cache.pop("k", None)
            elif step == "UPDATE":
                db = "NEW"
        else:
            if step == "GET_MISS":
                read_buf = cache.get("k")      # 可能为 None（miss）
            elif step == "READ_DB":
                read_buf = db                  # 读到的是「当时」的库值
            elif step == "SET_CACHE":
                cache["k"] = read_buf
    return cache.get("k"), db


def is_dirty(cache_v, db_v):
    """脏 = 缓存里残留旧值，而库已是新值。

    注意：缓存为空（None）**不算脏**——空是 miss，下一次读会回源拿到 NEW，
    结果是正确的。若把「空」也算脏，会把「先更库再删缓存」末尾那次 DEL
    误判成不一致，脏率被虚高（旧版就是这样得到 5/10 的）。
    """
    return cache_v is not None and cache_v != db_v


READER = ["GET_MISS", "READ_DB", "SET_CACHE"]
PLANS = [
    ("先删缓存后更新库", ["DEL", "UPDATE"]),
    ("先更新库后删缓存", ["UPDATE", "DEL"]),
]

for name, writer in PLANS:
    seqs = interleave(writer, READER)
    dirty = sum(1 for s in seqs if is_dirty(*simulate(s)))
    print("%s: 共 %d 种合法交错，其中 %d 种缓存残留旧值 (%.0f%%)"
          % (name, len(seqs), dirty, 100.0 * dirty / len(seqs)))

print("")
print("脏样本（先删缓存后更新库的典型交错）:")
seqs = interleave(["DEL", "UPDATE"], READER)
shown = 0
for s in seqs:
    c, d = simulate(s)
    if is_dirty(c, d) and shown < 3:
        print("  %s -> cache=%s, db=%s" % (
            " ".join("%s:%s" % (w, st) for w, st in s), c, d))
        shown += 1
print("结论: 先删缓存后更新库的脏窗口明显更大，工程上应选择「先更新库再删缓存」")
